def tr_noStop(s): return "".join(code[s[i:i+3]] for i in range(0,len(s)-3,3))

STARTS = ("ATG","GTG","TTG")
STOPS = ("TAA","TAG","TGA")

# find all ORFs on a strand for given frame: start in STARTS, run to first in-frame stop, or off-end
def orfs_in_frame(s, frame):
    out = []
    L2 = len(s)
    p = frame
    while p < L2-2:
        if s[p:p+3] in STARTS:
            q = p+3
            while q < L2-2:
                if s[q:q+3] in STOPS:
                    out.append((p, q+2, True))   # inclusive end index
                    p = q+3
                    break
                q += 3
            else:
                # ran off the end without a stop
                out.append((p, L2-1 - ((L2-1-p) % 3), False))
                p = L2
        else:
            p += 3
    return out

def report(strand, parent):
    print(f"===== {strand} strand =====")
    all_orfs = []
    for fr in range(3):
        for (p, q, has_stop) in orfs_in_frame(parent, fr):
            all_orfs.append((fr, p, q, has_stop))
    # longest no-stop runway per frame
    for fr in range(3):
        best = (0, None, None)
        cur_start = None
        for p in range(fr, len(parent)-2, 3):
            if parent[p:p+3] in STOPS:
                if cur_start is not None:
                    run = p - cur_start
                    if run > best[0]: best = (run, cur_start, p-1)
                    cur_start = None
            else:
