# --- nested array / inverted repeat scan, min hairpin stem 8 bp, loop 3-6 ---
def find_hairpins(s, stem=8, loop_min=3, loop_max=6):
    out=[]
    Ln=len(s)
    for i in range(Ln-2*stem-loop_max+1):
        a = s[i:i+stem]
        for sp in range(loop_min, loop_max+1):
            j = i+stem+sp
            b = s[j:j+stem]
            if len(b)<stem: break
            if a == revcomp(b):
                out.append((i, stem, sp))
    return out

h_fwd = find_hairpins(seq)
h_rev = find_hairpins(rc)
print("inverted repeats >=8 bp stem (fwd, 0-based):", h_fwd[:20], len(h_fwd))
print("inverted repeats >=8 bp stem (rev, rc coords):", h_rev[:20], len(h_rev))

# --- direct tandem repeats (>= 10 bp unit, >= 2 copies, period <= 8) ---
def find_tandem_repeats(s, unit_min=10, unit_max=20, min_copies=2):
    out=[]
    Ln=len(s)
    for start in range(Ln-unit_max):
        for u in range(unit_min, unit_max+1):
            if start+2*u > Ln: break
            unit = s[start:start+u]
            copies = 1
            while s[start+copies*u:start+(copies+1)*u] == unit:
                copies += 1
            if copies >= min_copies:
                out.append((start, u, copies, unit))
    return out

tr_fwd = find_tandem_repeats(seq)
tr_rev = find_tandem_repeats(rc)
print("tandem repeats (unit >=10):", tr_fwd[:20])
print("tandem repeats rc:", tr_rev[:20])

# --- microsatellites: 3-mers repeated >= 5 times ---
print("3-mer microsatellites (>=5 copies):")
for period in (2,3,4):
    found=set()
    for i in range(L - period*5+1):
        unit = seq[i:i+period]
        if len(set(unit))>2:  # require not just homopolymer
            continue
        # count repeats
        c=1
        while seq[i+c*period:i+(c+1)*period]==unit:
